namespace long_types {

template <typename... Ts> struct Tuple {};
template <typename K, typename V> struct Map {};
template <typename T> struct Vector {};
template <typename T> struct Optional {};

struct Coordinate {};
struct Measurement {};

auto index = Map<Vector<Tuple<Coordinate, Measurement>>, Optional<Tuple<Coordinate, Measurement>>>{};

auto wide = Tuple<int, long, unsigned, char, short, double, float, bool, signed char, unsigned short>{};

auto copy = index;

auto pairs = Map<Vector<Tuple<Coordinate, Measurement, Coordinate>>, Vector<Tuple<Coordinate, Measurement, Coordinate>>>{};

template <typename... Ts> using Bundle = Tuple<Ts...>;

Bundle<Map<Coordinate, Measurement>, Map<Measurement, Coordinate>, Vector<Coordinate>> bundle;

auto packed = Bundle<Map<Coordinate, Measurement>, Map<Measurement, Coordinate>>{};

void (*visit)(Coordinate, Measurement, Coordinate, Measurement, Coordinate, Measurement);

template <typename... Ts> void take(Ts... values);

void use() {
    take(Map<Vector<Tuple<Coordinate, Measurement>>, Optional<Tuple<Coordinate, Measurement>>>{}, 1);
}

using Dispatch = void (*)(void (*)(int), void (*)(long), void (*)(char), void (*)(short), void (*)(float),
                          void (*)(double), void (*)(bool), void (*)(unsigned), void (*)(signed char));
Dispatch dispatch;

}
